  self::assertTrue(defined(OrderLocalWorkflow::class.'::BEGIN_PLAN_REVIEW'),'Existing local DRAFT plans need a governed review entry.');self::assertTrue(defined(OrderLocalWorkflow::class.'::APPROVE_PLAN'));self::assertTrue(defined(OrderLocalWorkflow::class.'::PREPARE_INTENT'));
