  try {
   $begin=$this->body(OrderLocalWorkflow::BEGIN_PLAN_REVIEW,$order)+['plan_id'=>(string)$plan];$preview=$this->invoke($begin);self::assertStringContainsString('Confirm local fulfillment plan review entry',$preview);self::assertStringContainsString('Plan #'.$plan,$preview);self::assertStringContainsString('shipping_estimate: 4',$preview);$confirm=$this->confirmed($begin,$preview);self::assertStringContainsString('Local fulfillment plan entered review',$this->invoke($confirm));self::assertSame('REVIEW_REQUIRED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::fulfillment_plans().' WHERE id=%d',$plan)));self::assertSame('0',$wpdb->get_var($wpdb->prepare('SELECT approved_by FROM '.Tables::fulfillment_plans().' WHERE id=%d',$plan)));
   $wrong=$confirm;$wrong['action']=OrderLocalWorkflow::APPROVE_PLAN;$wrong['_wpnonce']=wp_create_nonce(OrderLocalWorkflow::APPROVE_PLAN.':'.$order);self::assertStringContainsString('changed',$this->invoke($wrong));
   $approve=$this->body(OrderLocalWorkflow::APPROVE_PLAN,$order)+['plan_id'=>(string)$plan];self::assertStringContainsString('Local fulfillment plan approved',$this->invoke($this->confirmed($approve,$this->invoke($approve))));self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::fulfillment_plans().' WHERE id=%d',$plan)));
   $prepare=$this->body(OrderLocalWorkflow::PREPARE_INTENT,$order)+['plan_id'=>(string)$plan];$confirm=$this->confirmed($prepare,$this->invoke($prepare));self::assertStringContainsString('BLOCKED local fulfillment preparation intent created',$this->invoke($confirm));$intent=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::fulfillment_intents().' WHERE order_id=%d ORDER BY id DESC LIMIT 1',$order),ARRAY_A);self::assertSame('BLOCKED',$intent['state']);self::assertSame('PREPARE_FULFILLMENT',$intent['intent_type']);self::assertSame($plan,(int)$intent['fulfillment_plan_id']);
   $held=(new \DigiForge\Orders\HeldFulfillmentPreparation())->prepare('personalized_pod',$order,(int)$intent['id']);self::assertNotWPError($held);self::assertTrue($held['release_hold']);self::assertFalse($held['external_execution_authorized']);self::assertFalse($held['preparation']['adapter_invoked']);self::assertStringContainsString('already exists',$this->invoke($confirm));$approved=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::fulfillment_plans().' WHERE id=%d',$plan),ARRAY_A);$draft=$this->body(OrderLocalWorkflow::DRAFT,$order)+['shipping_method'=>'standard','base_production_cost'=>'12','shipping_estimate'=>'5'];self::assertStringContainsString('DRAFT fulfillment plan created',$this->invoke($this->confirmed($draft,$this->invoke($draft))));self::assertSame($approved,$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::fulfillment_plans().' WHERE id=%d',$plan),ARRAY_A));
  }finally{remove_filter('pre_http_request',$deny);}self::assertSame(0,$http);self::assertTrue(\DigiForge\Core\Settings::safety_locked());
