 public function testPlanTransitionsDenyUnexpectedApprovalMetadataFromActualWrite():void {
  foreach([OrderLocalWorkflow::BEGIN_PLAN_REVIEW,OrderLocalWorkflow::APPROVE_PLAN]as $action){[$order,$plan]=$this->draftPlan();if($action===OrderLocalWorkflow::APPROVE_PLAN)PrintifyApiApprovalFixture::checked((new Repository())->transition('plan',$plan,'REVIEW_REQUIRED'));$body=$this->body($action,$order)+['plan_id'=>(string)$plan];$confirm=$this->confirmed($body,$this->invoke($body));$changed=false;global $wpdb;
   $corrupt=static function(string $sql)use(&$changed):string{if(!$changed&&str_starts_with($sql,'UPDATE `'.Tables::fulfillment_plans().'`')){$changed=true;$sql=str_replace(' SET '," SET `approved_by` = 999999, `approved_at` = '2020-01-01 00:00:00', ",$sql);if(str_contains($sql,"`state` = 'APPROVED'"))$sql=preg_replace("/(`approved_by`\\s*=\\s*)(?:[0-9]+|'[0-9]+')/", '${1}999999',$sql);}return $sql;};add_filter('query',$corrupt);try{$html=$this->invoke($confirm);}finally{remove_filter('query',$corrupt);}self::assertTrue($changed);self::assertStringNotContainsString($action===OrderLocalWorkflow::BEGIN_PLAN_REVIEW?'Local fulfillment plan entered review':'Local fulfillment plan approved',$html);self::assertSame($action===OrderLocalWorkflow::BEGIN_PLAN_REVIEW?'DRAFT':'REVIEW_REQUIRED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::fulfillment_plans().' WHERE id=%d',$plan)));self::assertSame('0',$wpdb->get_var($wpdb->prepare('SELECT approved_by FROM '.Tables::fulfillment_plans().' WHERE id=%d',$plan)));
  }
