 private function draftPlan(bool $rejectedHistory=false):array {[$order,$line]=$this->localOrder('REVIEW_REQUIRED',$rejectedHistory);PrintifyApiApprovalFixture::checked((new Repository())->transition('order',$order,'APPROVED'));$body=$this->body(OrderLocalWorkflow::DRAFT,$order)+['shipping_method'=>'standard','base_production_cost'=>'10','shipping_estimate'=>'4'];self::assertStringContainsString('DRAFT fulfillment plan created',$this->invoke($this->confirmed($body,$this->invoke($body))));global $wpdb;return [$order,(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.Tables::fulfillment_plans().' WHERE order_id=%d ORDER BY id DESC LIMIT 1',$order)),$line];}
 private function body(string $action,int $order):array {return ['action'=>$action,'order_id'=>(string)$order,'shop_key'=>'personalized_pod','_wpnonce'=>wp_create_nonce($action.':'.$order),'phase'=>'preview','return_url'=>home_url('/operations/')];}
 private function invoke(array $body):string {$post=$_POST;$hadMethod=array_key_exists('REQUEST_METHOD',$_SERVER);$method=$_SERVER['REQUEST_METHOD']??null;$_SERVER['REQUEST_METHOD']='POST';$_POST=$body;ob_start();try{try{do_action('admin_post_'.$body['action']);}catch(WPDieException $error){echo esc_html($error->getMessage());}return (string)ob_get_contents();}finally{ob_end_clean();$_POST=$post;if($hadMethod)$_SERVER['REQUEST_METHOD']=$method;else unset($_SERVER['REQUEST_METHOD']);}}
 private function confirmed(array $body,string $html):array {$doc=new DOMDocument();@$doc->loadHTML($html);foreach($doc->getElementsByTagName('input')as $input){$name=$input->getAttribute('name');if($name==='df_confirmation_tokens[REVIEW]')$body['df_confirmation_tokens']['REVIEW']=$input->getAttribute('value');elseif(str_starts_with($name,'df_confirmation_'))$body[$name]=$input->getAttribute('value');}$body['phase']='confirm';$body['df_confirm_review']='1';return $body;}
 private function localOrder(string $orderState='REVIEW_REQUIRED',bool $rejectedHistory=false):array {[, $mapping,$version]=$this->product();$repo=new Repository();$order=PrintifyApiApprovalFixture::checked($repo->createOrder(['channel'=>'etsy','shop_reference'=>'personalized_pod','environment'=>'test','currency'=>'USD','personalization_required'=>true]));$line=PrintifyApiApprovalFixture::checked($repo->addLineItem(['order_id'=>$order['id'],'product_version_id'=>$version,'provider_mapping_id'=>$mapping,'quantity'=>2]));$pod=new \DigiForge\POD\Repository();$schema=PrintifyApiApprovalFixture::checked($pod->createPersonalizationSchema(['product_version_id'=>$version,'schema_key'=>'local-order','version_label'=>'v1','field_definitions'=>[['key'=>'name','type'=>'text','required'=>true]]]));foreach(['VALIDATED','REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($pod->transition('personalization',(int)$schema['id'],$state));if($rejectedHistory){$rejected=PrintifyApiApprovalFixture::checked($repo->createPersonalization(['order_line_item_id'=>$line['id'],'personalization_schema_id'=>$schema['id'],'payload'=>['name'=>'Rejected synthetic sample']]));PrintifyApiApprovalFixture::checked($repo->reviewPersonalization((int)$rejected['id'],'REJECTED'));}$submission=PrintifyApiApprovalFixture::checked($repo->createPersonalization(['order_line_item_id'=>$line['id'],'personalization_schema_id'=>$schema['id'],'payload'=>['name'=>'Synthetic buyer']]));PrintifyApiApprovalFixture::checked($repo->reviewPersonalization((int)$submission['id'],'APPROVED'));PrintifyApiApprovalFixture::checked($repo->transition('order',(int)$order['id'],$orderState));\DigiForge\Core\Settings::protectProduction();return [(int)$order['id'],(int)$line['id']];}
